import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    adj = [set() for _ in range(26)]
    loops = [0] * 26
    for w in words:
        a = ord(w[0]) - 97
        b = ord(w[-1]) - 97
        if a == b:
            loops[a] += 1
        else:
            adj[a].add(b)
    if any(c >= 2 for c in loops):
        print('YES')
        return
    indeg = [0] * 26
    for a in range(26):
        for b in adj[a]:
            indeg[b] += 1
    stack = [v for v in range(26) if indeg[v] == 0]
    seen = 0
    while stack:
        v = stack.pop()
        seen += 1
        for b in adj[v]:
            indeg[b] -= 1
            if indeg[b] == 0:
                stack.append(b)
    print('YES' if seen < 26 else 'NO')

